from scipy import stats


def beta_update(a, b, k, n):
    return (a + k, b + n - k)


def gamma_update(shape, rate, counts):
    return (shape + sum(counts), rate + len(counts))


def normal_update(m0, s0, x, se):
    prec = 1 / s0 ** 2 + 1 / se ** 2
    mean = (m0 / s0 ** 2 + x / se ** 2) / prec
    return (mean, prec ** -0.5)


def credible_interval(dist, level):
    tail = (1 - level) / 2
    return (float(dist.ppf(tail)), float(dist.ppf(1 - tail)))
